/* =====================================================================
 * 主题（浅色 / 深色）
 * ---------------------------------------------------------------------
 * 只有这一处碰 data-theme；组件样式一律读 CSS 变量 —— 换主题不重绘任何 DOM，
 * 也不需要 JS 去改任何一个颜色值（"改一处漏十处"是这个项目最常见的回归）。
 * 偏好存 localStorage 的 ic.theme.v1；没存过就跟随系统。
 * ★ 这段必须最先执行：脚本在 body 末尾，跑在首屏绘制之前，所以不会闪白。
 * =================================================================== */
var THEME_KEY = "ic.theme.v1";
function storedTheme(){
  try{
    var v = localStorage.getItem(THEME_KEY);
    if (v === "light" || v === "dark") return v;
  }catch(e){ /* 隐私模式 / 禁用存储：跟着系统走 */ }
  try{
    if (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) return "dark";
  }catch(e){ /* 老环境没有 matchMedia */ }
  return "light";
}
function currentTheme(){
  var t = document.documentElement.getAttribute("data-theme");
  return t === "dark" ? "dark" : "light";
}
function applyTheme(t){
  t = (t === "dark") ? "dark" : "light";
  try{ document.documentElement.setAttribute("data-theme", t); }catch(e){}
  var b = $("btnTheme");
  if (b){
    b.setAttribute("aria-pressed", t === "dark" ? "true" : "false");
    b.setAttribute("aria-label", t === "dark" ? "切到浅色主题" : "切到深色主题");
    b.setAttribute("data-tip", t === "dark"
      ? "主题 · 现在是深色，点一下切浅色"
      : "主题 · 现在是浅色，点一下切深色");
  }
}
function setTheme(t){
  try{ localStorage.setItem(THEME_KEY, t); }catch(e){}
  applyTheme(t);
}
/* 系统主题变了、而用户从没手动选过 → 跟着变（别覆盖用户的选择） */
try{
  if (window.matchMedia){
    var _mq = window.matchMedia("(prefers-color-scheme: dark)");
    var _onScheme = function(){
      var stored = null;
      try{ stored = localStorage.getItem(THEME_KEY); }catch(e){}
      if (stored !== "light" && stored !== "dark") applyTheme(_mq.matches ? "dark" : "light");
    };
    if (_mq.addEventListener) _mq.addEventListener("change", _onScheme);
    else if (_mq.addListener) _mq.addListener(_onScheme);
  }
}catch(e){ /* 无所谓：不跟随系统也能用 */ }
applyTheme(storedTheme());

